/**
 * @file EmailDetailPage — full email detail view with inline editing, AI analysis, and reply drafting.
 *
 * Route: /emails/:emailId
 *
 * Features:
 *   - Displays email body (plain or HTML fallback), thread summary, and all action items.
 *   - Runs AI analysis on demand (analyseEmail); result is cached server-side in agent_cache.
 *   - Editable metadata: status, relation type, suggested tags. Changes are persisted via
 *     updateEmailMetadata() and mirrored to localStorage via setEmailOverrides().
 *   - Suggested reply: generated by generateSuggestedReply() and editable inline.
 *     Saved via updateSuggestedReply().
 *   - Voice-to-text transcription: records browser microphone audio, uploads to POST /stt/transcribe,
 *     and appends the transcript to the reply draft.
 *   - Thread view: lists sibling emails in the same thread via listEmailsInThread().
 *   - Raw JSON panel: shows the unprocessed API response for debugging.
 *
 * Data flow: getEmail() → normalizeEmailDetail() → merge localStorage overrides → component state.
 */

import React from 'react'
import { Link, useParams } from 'react-router-dom'
import { analyseEmail, generateSuggestedReply, getEmail, getRawEmail, listEmailsInThread, sendEmail, transcribeAudio, updateEmailMetadata, updateSuggestedReply, updateThreadSummary } from '../../api/client'
import { normalizeEmailDetail } from '../tools/normalizeEmail'
import { clearEmailOverrides, getEmailOverrides, setEmailOverrides } from '../tools/storage'
import { readSettings } from '../tools/storage'
import { Badge } from '../components/Badge'
import { Button } from '../components/Button'
import { Alert } from '../components/Alert'
import { Card, CardHeader } from '../components/Card'
import { InfoBox } from '../components/InfoBox'
import { Input, Textarea, Select, FormField } from '../components/Form'
import { SkeletonLine } from '../components/Skeleton'

function priorityTone(priority) {
  const p = (priority || '').toLowerCase()
  if (['high', 'urgent', 'p1', '1', 'critical'].includes(p)) return 'rose'
  if (['medium', 'p2', '2'].includes(p)) return 'amber'
  if (['low', 'p3', '3'].includes(p)) return 'green'
  return 'slate'
}

function stripEmailHeaders(text) {
  const lines = (text || '').split('\n')
  let i = 0
  while (i < lines.length && /^[A-Za-z-]+\s*:/.test(lines[i].trim())) i++
  while (i < lines.length && lines[i].trim() === '') i++
  return lines.slice(i).join('\n')
}

function splitSentences(text) {
  const t = (text || '').trim()
  if (!t) return []
  return t.split(/\n+/).flatMap((chunk) => chunk.split(/(?<=[.!?])\s+/)).map((s) => s.trim()).filter(Boolean)
}


export function EmailDetailPage() {
  const { emailId } = useParams()

  const [status, setStatus] = React.useState('loading')
  const [error, setError] = React.useState(null)
  const [email, setEmail] = React.useState(null)
  const [rawDetail, setRawDetail] = React.useState(null)
  const [viewMode, setViewMode] = React.useState('analysis')
  const [rawStatus, setRawStatus] = React.useState('idle')
  const [analysisStatus, setAnalysisStatus] = React.useState('idle')

  const [draftTags, setDraftTags] = React.useState('')
  const [draftPriority, setDraftPriority] = React.useState('')
  const [draftImportance, setDraftImportance] = React.useState('')
    const [draftSummary, setDraftSummary] = React.useState('')
    const [draftBriefSummary, setDraftBriefSummary] = React.useState('')
  const [actions, setActions] = React.useState([])

  const [summaryView, setSummaryView] = React.useState('summary') // 'summary' | 'body'
  const [responseDraft, setResponseDraft] = React.useState('')
  const [suggestStatus, setSuggestStatus] = React.useState('idle') // idle | loading
  const [sttStatus, setSttStatus] = React.useState('idle') // idle | listening | processing
  const [savingThreadSummary, setSavingThreadSummary] = React.useState(false)
  const [saveError, setSaveError] = React.useState(null)
  const [savingReply, setSavingReply] = React.useState(false)
  const [saveReplyError, setSaveReplyError] = React.useState(null)
  const [replyToAddress, setReplyToAddress] = React.useState('')
  const [gmailThreadId, setGmailThreadId] = React.useState('')
  const [rfcMessageId, setRfcMessageId] = React.useState('')
  const [sendStatus, setSendStatus] = React.useState('idle') // idle | sending | success | error
  const [sendError, setSendError] = React.useState(null)
  const [savingMetadata, setSavingMetadata] = React.useState(false)
  const [saveMetadataError, setSaveMetadataError] = React.useState(null)

  const [reanalysing, setReanalysing] = React.useState(false)
  const [threadHistory, setThreadHistory] = React.useState(null)
  const [threadHistoryStatus, setThreadHistoryStatus] = React.useState('idle')
  const [metaCollapsed, setMetaCollapsed] = React.useState(false)
  const [timelineCollapsed, setTimelineCollapsed] = React.useState(false)
  const [actionsCollapsed, setActionsCollapsed] = React.useState(false)
  const [sttVolume, setSttVolume] = React.useState(0)

  const overviewSenderRef = React.useRef(null)
  const mediaRecorderRef = React.useRef(null)
  const audioChunksRef = React.useRef([])
  const audioContextRef = React.useRef(null)
  const animFrameRef = React.useRef(null)
  const isMountedRef = React.useRef(true)

  const [settings] = React.useState(() => readSettings())
  const cache = email?.analysis?.raw || {}
  const confidencePercent = Math.max(0, Math.min(100, Math.round((Number(cache.confidence_score) || 0) * 100)))
  const rawBody =
    rawDetail?.mail?.body_plain ||
    rawDetail?.mail?.body_html ||
    ''

  const dirty = React.useMemo(() => {
    if (!email) return false
    const originalTags = (email.analysis?.tags || []).join(', ')
    const originalPriority = email.analysis?.priority || ''
    const originalSummary = email.analysis?.summary || ''
    const originalBriefSummary = email.analysis?.briefSummary || ''
    const originalActions = JSON.stringify(email.analysis?.actions || [])
    const currentActions = JSON.stringify(actions)
    return (
      draftTags.trim() !== originalTags.trim() ||
      draftPriority.trim() !== originalPriority.trim() ||
      draftSummary.trim() !== originalSummary.trim() ||
      draftBriefSummary.trim() !== originalBriefSummary.trim() ||
      currentActions !== originalActions
    )
  }, [email, draftTags, draftPriority, draftSummary, actions, draftBriefSummary])

  React.useEffect(() => {
    if (!emailId) return
    const controller = new AbortController()
    const sig = controller.signal

    setStatus('loading')
    setAnalysisStatus('loading')
    setRawStatus('idle')
    setError(null)

    const getEmailPromise = getEmail(emailId, { signal: sig })
    const analyseEmailPromise = analyseEmail(emailId, { signal: sig })

    // Chain 1: getEmail → show header immediately → fire getRawEmail in background
    getEmailPromise
      .then(async (overview) => {
        if (sig.aborted) return
        overviewSenderRef.current = overview?.sender
        const overviewNormalized = normalizeEmailDetail(overview)
        const messageId = overview?.email?.message_id || overview?.mail?.id || overviewNormalized?.raw?.email?.message_id
        setEmail(overviewNormalized)
        setReplyToAddress(overview?.sender?.email || '')
        setStatus('success')
        setRawStatus(messageId ? 'loading' : 'error')
        if (!messageId) return
        try {
          const rawResponse = await getRawEmail(messageId, { signal: sig })
          setRawDetail(rawResponse)
          setGmailThreadId(rawResponse?.mail?.thread_id || '')
          setRfcMessageId(rawResponse?.mail?.rfc_message_id || '')
          setRawStatus('success')
        } catch (rawError) {
          if (rawError?.name === 'AbortError') return
          setRawDetail(null)
          setRawStatus('error')
        }
      })
      .catch((err) => {
        if (err?.name === 'AbortError') return
        setError(err)
        setStatus('error')
        setAnalysisStatus('error')
        setRawStatus('error')
      })

    // Chain 2: both getEmail + analyseEmail → merge → set final email state with analysis
    Promise.all([getEmailPromise, analyseEmailPromise])
      .then(async ([overview, analysisRaw]) => {
        if (sig.aborted) return
        const normalized = normalizeEmailDetail({ ...(analysisRaw || overview), sender: overview?.sender })
        const overrides = getEmailOverrides(emailId)
        const merged = overrides
          ? {
              ...normalized,
              analysis: {
                ...normalized.analysis,
                ...(overrides.tags != null ? { tags: overrides.tags } : {}),
                ...(overrides.priority != null ? { priority: overrides.priority } : {}),
                ...(overrides.summary != null ? { summary: overrides.summary } : {}),
                ...(overrides.actions != null ? { actions: overrides.actions } : {}),
              },
            }
          : normalized

        const senderImportance = overview?.sender?.importance_score ?? null
        const resolvedImportance = merged.analysis?.importanceScore ?? senderImportance
        const mergedWithImportance = resolvedImportance !== merged.analysis?.importanceScore
          ? { ...merged, analysis: { ...merged.analysis, importanceScore: resolvedImportance } }
          : merged

        let finalThreadSummary = mergedWithImportance.threadSummary
        if (!mergedWithImportance.threadSummary && mergedWithImportance.analysis?.briefSummary && mergedWithImportance.threadId) {
          try {
            await updateThreadSummary(mergedWithImportance.threadId, mergedWithImportance.analysis.briefSummary, { signal: sig })
            finalThreadSummary = mergedWithImportance.analysis.briefSummary
          } catch (err) {
            if (err?.name !== 'AbortError') console.error('Auto-save thread summary failed:', err)
          }
        }

        setEmail({ ...mergedWithImportance, threadSummary: finalThreadSummary })
        setDraftTags((mergedWithImportance.analysis?.tags || []).join(', '))
        setDraftPriority(mergedWithImportance.analysis?.priority || '')
        setDraftImportance(mergedWithImportance.analysis?.importanceScore != null ? String(mergedWithImportance.analysis.importanceScore) : '')
        setDraftSummary(mergedWithImportance.analysis?.summary || '')
        setDraftBriefSummary(mergedWithImportance.analysis?.briefSummary || '')
        setActions(mergedWithImportance.analysis?.actions || [])
        setResponseDraft(overrides?.responseDraft || stripEmailHeaders(mergedWithImportance.analysis?.suggestedReply || ''))
        setAnalysisStatus('success')
        setStatus('success')
      })
      .catch((err) => {
        if (err?.name === 'AbortError') return
        setAnalysisStatus('error')
      })

    return () => controller.abort()
  }, [emailId])

  React.useEffect(() => {
    if (!emailId || status !== 'success' || analysisStatus !== 'success') return
    const id = window.setTimeout(() => {
      const responseTrimmed = (responseDraft || '').trim()
      const shouldSave = dirty || responseTrimmed.length > 0
      if (!shouldSave) {
        clearEmailOverrides(emailId)
        return
      }

      setEmailOverrides(emailId, {
        tags: draftTags
          .split(',')
          .map((t) => t.trim())
          .filter(Boolean),
        priority: draftPriority || '',
        summary: draftSummary || '',
          briefSummary: draftBriefSummary || '',
        actions: actions || [],
        responseDraft: responseDraft || '',
      })
    }, 350)
    return () => window.clearTimeout(id)
  }, [emailId, status, dirty, draftTags, draftPriority, draftSummary, draftBriefSummary, actions, responseDraft])

  React.useEffect(() => {
    if (!email?.threadId) return
    const controller = new AbortController()
    setThreadHistoryStatus('loading')
    listEmailsInThread(email.threadId, { signal: controller.signal })
      .then((items) => { setThreadHistory(items); setThreadHistoryStatus('success') })
      .catch((err) => { if (err?.name !== 'AbortError') setThreadHistoryStatus('error') })
    return () => controller.abort()
  }, [email?.threadId])

  React.useEffect(() => {
    isMountedRef.current = true
    return () => {
      isMountedRef.current = false
      cancelAnimationFrame(animFrameRef.current)
      audioContextRef.current?.close()
    }
  }, [])

  function resetEdits() {
    if (!email) return
    clearEmailOverrides(emailId)
    setDraftTags((email.analysis?.tags || []).join(', '))
    setDraftPriority(email.analysis?.priority || '')
    setDraftImportance(email.analysis?.importanceScore != null ? String(email.analysis.importanceScore) : '')
    setDraftSummary(email.analysis?.summary || '')
      setDraftBriefSummary(email.analysis?.briefSummary || '')
    setActions(email.analysis?.actions || [])
    setResponseDraft(email.analysis?.suggestedReply || '')
  }

  async function handleSaveThreadSummary() {
    if (!email?.threadId || savingThreadSummary) return
    setSavingThreadSummary(true)
    setSaveError(null)
    try {
      await updateThreadSummary(email.threadId, draftSummary)
      setEmail((prev) => prev ? { ...prev, threadSummary: draftSummary } : prev)
    } catch (err) {
      setSaveError(err?.message || 'Save failed')
    } finally {
      setSavingThreadSummary(false)
    }
  }

  async function handleSaveMetadata() {
    if (!emailId || savingMetadata) return
    setSavingMetadata(true)
    setSaveMetadataError(null)
    const tagList = draftTags.split(',').map((t) => t.trim()).filter(Boolean)
    const importance = draftImportance ? Number(draftImportance) : null
    try {
      await updateEmailMetadata(emailId, { tags: tagList, importance })
      setEmail((prev) => prev
        ? { ...prev, analysis: { ...prev.analysis, tags: tagList, importanceScore: importance } }
        : prev)
    } catch (err) {
      setSaveMetadataError(err?.message || 'Save failed')
    } finally {
      setSavingMetadata(false)
    }
  }

  function addAction() {
    setActions((prev) => [...prev, { text: '', due: '' }])
  }

  function updateAction(idx, patch) {
    setActions((prev) => prev.map((a, i) => (i === idx ? { ...a, ...patch } : a)))
  }

  function removeAction(idx) {
    setActions((prev) => prev.filter((_, i) => i !== idx))
  }

  async function suggestResponse() {
    if (!emailId) return
    setSuggestStatus('loading')
    try {
      const result = await generateSuggestedReply(emailId)
      const reply = stripEmailHeaders(result?.suggested_reply || '')
      setResponseDraft(reply)
      setEmail((prev) => prev
        ? { ...prev, analysis: { ...prev.analysis, suggestedReply: reply } }
        : prev)
    } catch (err) {
      console.error('Reply generation failed:', err)
    } finally {
      setSuggestStatus('idle')
    }
  }

  async function handleSaveReply() {
    if (!emailId || savingReply) return
    setSavingReply(true)
    setSaveReplyError(null)
    try {
      await updateSuggestedReply(emailId, responseDraft)
      setEmail((prev) => prev
        ? { ...prev, analysis: { ...prev.analysis, suggestedReply: responseDraft } }
        : prev)
    } catch (err) {
      setSaveReplyError(err?.message || 'Save failed')
    } finally {
      setSavingReply(false)
    }
  }

  async function handleRespond() {
    if (!responseDraft.trim() || sendStatus === 'sending') return
    const replySubject = email?.subject?.startsWith('Re:') ? email.subject : `Re: ${email?.subject || ''}`
    const confirmed = window.confirm(`Send reply to ${replyToAddress}?\n\nSubject: ${replySubject}`)
    if (!confirmed) return
    setSendStatus('sending')
    setSendError(null)
    try {
      await sendEmail({
        to: replyToAddress,
        subject: replySubject,
        body: responseDraft,
        thread_id: gmailThreadId || null,
        in_reply_to: rfcMessageId || null,
      })
      setResponseDraft('')
      setSendStatus('idle')
    } catch (err) {
      setSendError(err?.message || 'Failed to send')
      setSendStatus('error')
    }
  }

  function startVolumeMonitor(stream) {
    const ctx = new AudioContext()
    audioContextRef.current = ctx
    const analyser = ctx.createAnalyser()
    analyser.fftSize = 256
    ctx.createMediaStreamSource(stream).connect(analyser)
    const data = new Uint8Array(analyser.frequencyBinCount)
    function tick() {
      analyser.getByteFrequencyData(data)
      const avg = data.reduce((s, v) => s + v, 0) / data.length
      if (isMountedRef.current) setSttVolume(Math.round((avg / 255) * 100))
      animFrameRef.current = requestAnimationFrame(tick)
    }
    animFrameRef.current = requestAnimationFrame(tick)
  }

  function stopVolumeMonitor() {
    cancelAnimationFrame(animFrameRef.current)
    audioContextRef.current?.close()
    audioContextRef.current = null
    setSttVolume(0)
  }

  async function startRecording() {
    try {
      const constraints = {
        audio: settings?.sttDeviceId ? { deviceId: { exact: settings.sttDeviceId } } : true,
      }
      const stream = await navigator.mediaDevices.getUserMedia(constraints)
      audioChunksRef.current = []
      startVolumeMonitor(stream)
      const mimeType = MediaRecorder.isTypeSupported('audio/webm') ? 'audio/webm' : ''
      const mr = new MediaRecorder(stream, mimeType ? { mimeType } : {})
      const recordedMimeType = mr.mimeType || 'audio/webm'
      mr.ondataavailable = (e) => { if (e.data.size > 0) audioChunksRef.current.push(e.data) }
      mr.onstop = async () => {
        stream.getTracks().forEach((t) => t.stop())
        stopVolumeMonitor()
        if (!isMountedRef.current) return
        const blob = new Blob(audioChunksRef.current, { type: recordedMimeType })
        setSttStatus('processing')
        try {
          const { text } = await transcribeAudio(blob, { lang: settings?.sttLang || 'pl' })
          if (isMountedRef.current && text) {
            setResponseDraft((prev) => (prev ? prev + ' ' + text : text))
          }
        } catch {
          // silently ignore transcription errors
        } finally {
          if (isMountedRef.current) setSttStatus('idle')
        }
      }
      mediaRecorderRef.current = mr
      mr.start()
      setSttStatus('listening')
    } catch {
      setSttStatus('idle')
    }
  }

  function stopRecording() {
    mediaRecorderRef.current?.stop()
    mediaRecorderRef.current = null
  }

  function toggleStt() {
    if (sttStatus === 'listening') { stopRecording(); return }
    if (sttStatus === 'idle') { startRecording(); return }
  }

  async function handleReanalyse() {
    if (!emailId || reanalysing) return
    setReanalysing(true)
    try {
      const analysisRaw = await analyseEmail(emailId, { forceRegeneration: true, signal: null })
      const normalized = normalizeEmailDetail({ ...(analysisRaw || email), sender: overviewSenderRef.current })
        setEmail(normalized)
        setDraftTags((normalized.analysis?.tags || []).join(', '))
        setDraftPriority(normalized.analysis?.priority || '')
        setDraftImportance(normalized.analysis?.importanceScore != null ? String(normalized.analysis.importanceScore) : '')
        setDraftSummary(normalized.analysis?.summary || '')
        setDraftBriefSummary(normalized.analysis?.briefSummary || '')
        setActions(normalized.analysis?.actions || [])
        setResponseDraft(normalized.analysis?.suggestedReply || '')
    } catch (err) {
        console.error('Re-analysis failed:', err)
        // Opcjonalnie: ustawienie błędu w UI
    } finally {
        setReanalysing(false)
    }
}

  if (status === 'loading') {
    return (
      <div className="space-y-4">
        <Card>
          <SkeletonLine height="h-5" width="w-2/3" />
          <SkeletonLine height="h-4" width="w-1/2" className="mt-2" />
        </Card>
        <Card>
          <SkeletonLine height="h-4" width="w-40" />
          <SkeletonLine height="h-24" className="mt-3" />
        </Card>
      </div>
    )
  }

  if (status === 'error') {
    return (
      <Alert
        variant="error"
        title="Couldn't load email"
        actions={
          <Button as={Link} to="/" variant="secondary">
            Back to inbox
          </Button>
        }
      >
        {String(error?.message || error)}
      </Alert>
    )
  }

  const tags = draftTags
    .split(',')
    .map((t) => t.trim())
    .filter(Boolean)

  const sentences = splitSentences(draftSummary)
  const tooLongSummary = sentences.length > 5

  return (
    <div className="space-y-4">
      {/* Header card */}
      <Card>
        <div className="flex flex-col gap-2 md:flex-row md:items-start md:justify-between">
          <div className="space-y-1">
            <div className="text-xs text-slate-500">
              <Link to="/" className="hover:underline">
                Inbox
              </Link>{' '}
              <span className="text-slate-300">/</span> Email
            </div>
            <div className="text-lg font-semibold">{email.subject || '(No subject)'}</div>
            <div className="text-sm text-slate-600">{email.from || '(Unknown sender)'}</div>
            {email.date ? (
              <div className="text-xs text-slate-400">
                {(() => { try { return new Date(email.date).toLocaleString() } catch { return email.date } })()}
              </div>
            ) : null}
          </div>
          <div className="flex flex-wrap items-center gap-2">
            {dirty ? <Badge tone="amber">Edited (local)</Badge> : <Badge tone="slate">Synced</Badge>}
            <Button variant={viewMode === 'analysis' ? 'primary' : 'secondary'} onClick={() => setViewMode('analysis')}>
              AI Analysis
            </Button>
            <Button variant={viewMode === 'raw' ? 'primary' : 'secondary'} onClick={() => setViewMode('raw')}>
              Raw Email
            </Button>
            <Button variant="ghost" onClick={resetEdits} disabled={!dirty}>
              Reset edits
            </Button>
          </div>
        </div>
        <div className="mt-3 flex flex-wrap items-center gap-2">
          {draftPriority ? <Badge tone={priorityTone(draftPriority)}>{draftPriority.toUpperCase()}</Badge> : null}
          {draftImportance ? <Badge tone="blue">importance {draftImportance}/5</Badge> : null}
          {tags.map((t) => (
            <Badge key={t} tone="violet">
              {t}
            </Badge>
          ))}
        </div>
      </Card>

      <div className="grid grid-cols-1 gap-4 lg:grid-cols-12">
        <section className="lg:col-span-7 space-y-4">
          {viewMode === 'analysis' ? (
            <>
              <Card>
                <CardHeader
                  title={
                    <div className="inline-flex rounded-lg border border-slate-200 bg-slate-100 p-0.5 text-sm font-medium">
                      {['summary', 'body'].map((opt) => (
                        <button
                          key={opt}
                          type="button"
                          onClick={() => setSummaryView(opt)}
                          className={`rounded-md px-4 py-1.5 transition ${
                            summaryView === opt
                              ? 'bg-slate-900 text-white font-bold shadow-sm'
                              : 'text-slate-500 hover:text-slate-700'
                          }`}
                        >
                          {opt === 'summary' ? 'AI Summary' : 'Email body'}
                        </button>
                      ))}
                    </div>
                  }
                  actions={summaryView === 'summary' ? (
                    <div className="flex items-center gap-2">
                      {tooLongSummary ? <Badge tone="amber">Over 5 sentences</Badge> : null}
                      <span className="text-xs text-slate-500">
                        {sentences.length ? `${sentences.length} sentences` : ''}
                      </span>
                      {email?.threadId && (
                        <Button
                          variant="primary"
                          size="sm"
                          disabled={
                            savingThreadSummary ||
                            !draftSummary.trim() ||
                            draftSummary.trim() === (email.threadSummary || '').trim()
                          }
                          onClick={handleSaveThreadSummary}
                        >
                          {savingThreadSummary ? 'Saving…' : 'Save'}
                        </Button>
                      )}
                    </div>
                  ) : null}
                />
                {summaryView === 'body' ? (
                  <InfoBox className="max-h-[420px] overflow-auto whitespace-pre-wrap text-slate-800">
                    {rawBody || email.body || <span className="text-slate-500">(No body returned)</span>}
                  </InfoBox>
                ) : analysisStatus === 'loading' ? (
                  <>
                    <SkeletonLine height="h-20" />
                    <SkeletonLine height="h-16" className="mt-3" />
                  </>
                ) : (
                  <>{(
                      <InfoBox className="mb-3">
                          <div className="text-xs font-medium text-slate-700">Quick view</div>
                          <p className="text-sm text-slate-700">
                              {draftBriefSummary}
                          </p>
                          {/*<ol className="mt-2 list-decimal space-y-1 pl-4 text-sm text-slate-700">*/}
                          {/*  {sentences.slice(0, 6).map((s, i) => (*/}
                          {/*    <li key={i}>{s}</li>*/}
                          {/*  ))}*/}
                          {/*</ol>*/}
                      </InfoBox>
                  )}
                    <Textarea
                      rows={4}
                      value={draftSummary}
                      onChange={(e) => setDraftSummary(e.target.value)}
                      placeholder="LLM summary will appear here."
                    />
                    {tooLongSummary && (
                      <Alert
                        variant="warning"
                        className="mt-2"
                        actions={
                          <Button
                            variant="secondary"
                            size="sm"
                            onClick={() => setDraftSummary(sentences.slice(0, 5).join(' '))}
                          >
                            Trim to 5
                          </Button>
                        }
                      >
                        Acceptance criteria says max 5 sentences. You can trim automatically and then edit.
                      </Alert>
                    )}
                    {saveError && (
                      <Alert variant="error" className="mt-2">{saveError}</Alert>
                    )}

                  </>
                )}
              </Card>

              <Card>
                <CardHeader
                  title="Extracted actions (editable)"
                  actions={
                    <div className="flex items-center gap-2">
                      <Button variant="secondary" size="sm" onClick={addAction}>
                        Add action
                      </Button>
                      <button onClick={() => setActionsCollapsed(c => !c)} className="p-1 text-slate-400 hover:text-slate-600" title={actionsCollapsed ? 'Expand' : 'Collapse'}>
                        <svg className={`h-4 w-4 transition-transform duration-150 ${actionsCollapsed ? '' : 'rotate-180'}`} fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
                          <path strokeLinecap="round" strokeLinejoin="round" d="M19 9l-7 7-7-7" />
                        </svg>
                      </button>
                    </div>
                  }
                />
                {!actionsCollapsed && (actions.length === 0 ? (
                  <div className="text-sm text-slate-600">No actions detected. Add one if needed.</div>
                ) : (
                  <div className="space-y-2">
                    {actions.map((a, idx) => (
                      <div key={idx} className="grid grid-cols-1 gap-2 rounded-lg border border-slate-200 p-3 md:grid-cols-12">
                        <FormField label="Task" className="md:col-span-8">
                          <Input
                            value={a.task || ''}
                            onChange={(e) => updateAction(idx, { task: e.target.value })}
                            placeholder='e.g. "Confirm delivery time"'
                          />
                        </FormField>
                        <FormField label="Deadline" className="md:col-span-3">
                          <Input
                            value={a.deadline || ''}
                            onChange={(e) => updateAction(idx, { deadline: e.target.value })}
                            placeholder='e.g. "2026-04-02"'
                          />
                        </FormField>
                        <div className="md:col-span-1 flex items-end">
                          <Button variant="ghost" size="sm" onClick={() => removeAction(idx)} title="Remove">
                            ✕
                          </Button>
                        </div>
                      </div>
                    ))}
                  </div>
                ))}
              </Card>

              <Card>
                <CardHeader
                  title="Response suggestion (editable)"
                  actions={
                    <div className="flex items-center gap-2">
                      <div className="flex items-end gap-1">
                        {sttStatus === 'listening' && (
                          <div className="flex items-end gap-[2px] h-4 mb-0.5">
                            {[4,6,8,10,12,14,12,10,8,6].map((h, i) => {
                              const threshold = (i / 10) * 100
                              const active = sttVolume > threshold
                              const colorClass = i >= 8 ? 'bg-rose-400' : i >= 6 ? 'bg-amber-400' : 'bg-green-400'
                              return (
                                <div
                                  key={i}
                                  className={`w-1 rounded-sm transition-colors ${active ? colorClass : 'bg-gray-200'}`}
                                  style={{ height: `${h}px` }}
                                />
                              )
                            })}
                          </div>
                        )}
                        <Button
                          variant={sttStatus === 'listening' ? 'danger' : 'secondary'}
                          size="sm"
                          onClick={toggleStt}
                          title={sttStatus === 'listening' ? 'Stop recording' : sttStatus === 'processing' ? 'Processing audio…' : 'Dictate into the draft'}
                          disabled={suggestStatus === 'loading' || sttStatus === 'processing'}
                        >
                          {sttStatus === 'listening' ? 'Stop' : sttStatus === 'processing' ? 'Processing…' : 'Mic'}
                        </Button>
                      </div>
                      <Button
                        variant="secondary"
                        size="sm"
                        onClick={suggestResponse}
                        disabled={suggestStatus === 'loading'}
                        title="Generate an AI reply draft"
                      >
                        {suggestStatus === 'loading' ? 'Suggesting…' : 'Suggest response'}
                      </Button>
                      <Button
                        variant="primary"
                        size="sm"
                        disabled={
                          savingReply ||
                          !responseDraft.trim() ||
                          responseDraft.trim() === (email?.analysis?.suggestedReply || '').trim()
                        }
                        onClick={handleSaveReply}
                      >
                        {savingReply ? 'Saving…' : 'Save'}
                      </Button>
                    </div>
                  }
                />
                <Textarea
                  rows={5}
                  value={responseDraft}
                  onChange={(e) => setResponseDraft(e.target.value)}
                  placeholder="Draft will appear here. You can edit before sending."
                />
                {saveReplyError && (
                  <Alert variant="error" className="mt-2">{saveReplyError}</Alert>
                )}
                {sendError && (
                  <Alert variant="error" className="mt-2">{sendError}</Alert>
                )}
                <div className="mt-2 flex justify-end">
                  <Button
                    variant="primary"
                    disabled={
                      !responseDraft.trim() ||
                      sendStatus === 'sending' ||
                      !replyToAddress ||
                      rawStatus !== 'success' ||
                      analysisStatus !== 'success'
                    }
                    title={
                      rawStatus !== 'success' || analysisStatus !== 'success'
                        ? 'Waiting for email to finish loading…'
                        : undefined
                    }
                    onClick={handleRespond}
                  >
                    {sendStatus === 'sending' ? 'Sending…' : 'Respond'}
                  </Button>
                </div>
              </Card>
            </>
          ) : (
            <Card>
              <CardHeader
                title="Raw email"
                description={
                  rawStatus === 'success'
                    ? `Fetched without LLM in ${Number(rawDetail?.processing_time_ms || 0).toFixed(2)} ms.`
                    : 'Inspect the unprocessed Gmail payload and body.'
                }
              />
              {rawStatus === 'loading' ? (
                <>
                  <SkeletonLine height="h-6" width="w-48" />
                  <SkeletonLine height="h-40" className="mt-3" />
                </>
              ) : rawStatus === 'error' ? (
                <Alert variant="warning">Raw Gmail view is unavailable for this message.</Alert>
              ) : (
                <>
                  <InfoBox className="max-h-[420px] overflow-auto whitespace-pre-wrap text-slate-800">
                    {rawBody || <span className="text-slate-500">(No raw body returned)</span>}
                  </InfoBox>
                  <pre className="mt-3 max-h-[360px] overflow-auto rounded-lg border border-slate-200 bg-slate-50 p-3 text-xs text-slate-800">
                    {JSON.stringify(rawDetail, null, 2)}
                  </pre>
                </>
              )}
            </Card>
          )}
        </section>

        <aside className="lg:col-span-5 space-y-4">
          <Card>
            <CardHeader
              title={viewMode === 'analysis' ? 'AI metadata (editable)' : 'Processing stats'}
              description={
                viewMode === 'analysis'
                  ? 'Shows the detailed AgentCacheModel state returned by the backend.'
                  : 'Compare raw retrieval speed with the analysed view.'
              }
              actions={
                <button onClick={() => setMetaCollapsed(c => !c)} className="p-1 text-slate-400 hover:text-slate-600" title={metaCollapsed ? 'Expand' : 'Collapse'}>
                  <svg className={`h-4 w-4 transition-transform duration-150 ${metaCollapsed ? '' : 'rotate-180'}`} fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
                    <path strokeLinecap="round" strokeLinejoin="round" d="M19 9l-7 7-7-7" />
                  </svg>
                </button>
              }
            />
            {!metaCollapsed && (viewMode === 'analysis' ? (
              <>
                <div className="grid grid-cols-1 gap-3 md:grid-cols-2 lg:grid-cols-1">
                  <FormField label="Priority">
                    <Select value={draftPriority} onChange={(e) => setDraftPriority(e.target.value)}>
                      <option value="">(none)</option>
                      <option value="high">High</option>
                      <option value="medium">Medium</option>
                      <option value="low">Low</option>
                    </Select>
                  </FormField>
                  <FormField label="Importance (1–5)">
                    <Select value={draftImportance} onChange={(e) => setDraftImportance(e.target.value)}>
                      <option value="">(none)</option>
                      <option value="1">1 – Very low</option>
                      <option value="2">2 – Low</option>
                      <option value="3">3 – Medium</option>
                      <option value="4">4 – High</option>
                      <option value="5">5 – Critical</option>
                    </Select>
                  </FormField>
                  <FormField label="Tags (comma-separated)">
                    <Input
                      value={draftTags}
                      onChange={(e) => setDraftTags(e.target.value)}
                      placeholder="Logistics, Sponsorship, Catering"
                    />
                  </FormField>
                </div>
                <div className="mt-4 space-y-3">
                  <InfoBox>
                    <div className="flex items-center justify-between gap-3">
                      <div className="font-medium text-slate-900">Model confidence</div>
                      <Badge tone={confidencePercent >= 70 ? 'green' : confidencePercent >= 40 ? 'amber' : 'rose'}>
                        {confidencePercent}%
                      </Badge>
                    </div>
                    <div className="mt-3 h-2 overflow-hidden rounded-full bg-slate-200">
                      <div className="h-full rounded-full bg-slate-900" style={{ width: `${confidencePercent}%` }} />
                    </div>
                    <div className="mt-2 text-xs text-slate-600">
                      Model used: <span className="font-medium text-slate-900">{cache.model_used || email?.analysis?.modelUsed || 'unknown'}</span>
                    </div>
                  </InfoBox>

                </div>
                {saveMetadataError && (
                  <Alert variant="error" className="mt-3">{saveMetadataError}</Alert>
                )}
                <div className="mt-4">
                  <Button
                    variant="primary"
                    disabled={
                      savingMetadata ||
                      (draftTags.trim() === (email?.analysis?.tags || []).join(', ').trim() &&
                       draftImportance === (email?.analysis?.importanceScore != null ? String(email.analysis.importanceScore) : ''))
                    }
                    onClick={handleSaveMetadata}
                  >
                    {savingMetadata ? 'Saving…' : 'Save'}
                  </Button>
                </div>
              </>
            ) : (
              <div className="space-y-3">
                <InfoBox>Raw processing time: {Number(rawDetail?.processing_time_ms || 0).toFixed(2)} ms</InfoBox>
                <InfoBox>Analysis processing time: {Number(email?.processingTimeMs || 0).toFixed(2)} ms</InfoBox>
                <InfoBox>Model used: {cache.model_used || email?.analysis?.modelUsed || 'unknown'}</InfoBox>
              </div>
            ))}
          </Card>

          <Card>
            <CardHeader
              title="History timeline"
              description="Other emails in this thread."
              actions={
                <button onClick={() => setTimelineCollapsed(c => !c)} className="p-1 text-slate-400 hover:text-slate-600" title={timelineCollapsed ? 'Expand' : 'Collapse'}>
                  <svg className={`h-4 w-4 transition-transform duration-150 ${timelineCollapsed ? '' : 'rotate-180'}`} fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
                    <path strokeLinecap="round" strokeLinejoin="round" d="M19 9l-7 7-7-7" />
                  </svg>
                </button>
              }
            />
            {!timelineCollapsed && (!email?.threadId ? (
              <InfoBox>No thread ID — this email is not part of a thread.</InfoBox>
            ) : threadHistoryStatus === 'loading' || threadHistoryStatus === 'idle' ? (
              <>
                <SkeletonLine height="h-16" />
                <SkeletonLine height="h-16" className="mt-2" />
              </>
            ) : threadHistoryStatus === 'error' ? (
              <InfoBox>Could not load thread history.</InfoBox>
            ) : !threadHistory || threadHistory.length === 0 ? (
              <InfoBox>No other emails in this thread.</InfoBox>
            ) : (
              <ol className="mt-2 max-h-96 space-y-2 overflow-y-auto">
                {threadHistory.map((item) => (
                  <li key={item.id}>
                    <Link
                      to={`/emails/${item.id}`}
                      className={`block rounded-lg border p-3 transition hover:bg-slate-50 ${item.id === emailId ? 'border-blue-400 bg-blue-50' : 'border-slate-200 bg-white'}`}
                    >
                      <div className="flex flex-wrap items-center justify-between gap-1">
                        <div className="text-xs font-semibold text-slate-800 truncate">{item.sender_name || item.sender_email || 'Unknown'}</div>
                        {item.received_at ? (
                          <div className="text-xs text-slate-500 flex-shrink-0">
                            {(() => { try { return new Date(item.received_at).toLocaleDateString() } catch { return '' } })()}
                          </div>
                        ) : null}
                      </div>
                      <div className="mt-0.5 text-xs font-medium text-slate-700 truncate">{item.subject || '(No subject)'}</div>
                      {item.body_preview ? (
                        <div className="mt-1 text-xs text-slate-500 line-clamp-2">{item.body_preview}</div>
                      ) : null}
                    </Link>
                  </li>
                ))}
              </ol>
            ))}
          </Card>
            <Card >
                <Button
                    variant="ghost"
                    className="w-full justify-center"
                    disabled={reanalysing || status !== 'success'}
                    onClick={handleReanalyse}
                >
                    {reanalysing ? 'Analysing..' : 'Re-analyze'}
                </Button>
            </Card>
        </aside>
      </div>

    </div>
  )
}
